// Nœud Code « Générer code » — JavaScript, mode « Run Once for Each Item »
// Nécessite NODE_FUNCTION_ALLOW_BUILTIN=crypto (déjà dans docker-compose.yml)
const crypto = require('crypto');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
const code = String(crypto.randomInt(0, 1000000)).padStart(6, '0');   // 000000 à 999999
return { json: {
  email: $json.email,
  code,                                   // en clair : uniquement pour le mail
  code_hash: sha256(code),
  session_hash: sha256($json.sessionId),  // lie le code à cette conversation
} };

// Nœud Code « Parse commande » — mode « Run Once for Each Item », langage JavaScript
const text = String($json.chatInput ?? '').trim();
const sessionId = $json.sessionId;
const FORMAT = 'Commandes : /connexion ton@email.com puis /code 123456';

if (text.length > 500) {
  return { json: { kind: 'error', reply: 'Message trop long (500 caractères max).', sessionId } };
}

let m = text.match(/^\/connexion\s+([^\s@]+@[^\s@]+\.[^\s@]+)$/i);
if (m && m[1].length <= 254) {
  return { json: { kind: 'login', email: m[1].toLowerCase(), sessionId } };
}

m = text.match(/^\/code\s+(\d{6})$/);
if (m) {
  return { json: { kind: 'code', code: m[1], sessionId } };
}

if (/^\/logout$/i.test(text)) {
  return { json: { kind: 'logout', sessionId } };
}

// Commandes RGPD : elles passent par la branche « chat » (donc par la vérif de session)
// avec un champ cmd. Elles ne vont JAMAIS au LLM : c'est le Router qui les aiguille.
const RGPD = {
  '/accepte': 'accept',
  '/stop': 'stop',
  'stop': 'stop',
  '/reprendre': 'resume',
  '/mesdonnees': 'mydata',
  '/supprimer confirmer': 'delete',
};
const key = text.toLowerCase().replace(/\s+/g, ' ');
if (RGPD[key]) {
  return { json: { kind: 'chat', cmd: RGPD[key], chatInput: '', sessionId } };
}

// Suppression en 2 temps : /supprimer seul ne fait qu'avertir (action irréversible)
if (key === '/supprimer') {
  return { json: { kind: 'error', reply: 'Attention : ton compte, tes préférences et ton historique seront supprimés définitivement. Pour confirmer, tape "/supprimer confirmer"', sessionId } };
}

// Demande RGPD en langage naturel : on montre la commande au lieu de laisser le LLM décider
if (/supprim\w*\s+(mes|mon|toutes?)\b|efface\w*\s+(mes|mon)\b/i.test(text)) {
  return { json: { kind: 'error', reply: 'Pour supprimer ton compte et tes données, tape /supprimer', sessionId } };
}
if (/d[ée]sinscri|d[ée]sabonn/i.test(text)) {
  return { json: { kind: 'error', reply: 'Pour ne plus recevoir la newsletter, tape /stop (et /reprendre pour revenir).', sessionId } };
}

// Garde-fou : une commande mal formée ou cachée dans une phrase ne part JAMAIS au LLM
if (/\/(connexion|code|logout|accepte|stop|reprendre|mesdonnees|supprimer)/i.test(text)) {
  return { json: { kind: 'error', reply: 'Format invalide. ' + FORMAT, sessionId } };
}

return { json: { kind: 'chat', cmd: null, chatInput: text, sessionId } };

// Nœud Code « Hasher saisie »
const crypto = require('crypto');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
return { json: { code_hash: sha256($json.code), session_hash: sha256($json.sessionId) } };

// Nœud Code « Hasher session » — mode « Run Once for Each Item », langage JavaScript
// On garde chatInput (pour le LLM) et cmd (commande RGPD), et on ajoute le hash du sessionId.
const crypto = require('crypto');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
return { json: { chatInput: $json.chatInput, cmd: $json.cmd ?? null, session_hash: sha256($json.sessionId) } };

// Nœud Code « Hasher session » — mode « Run Once for Each Item », langage JavaScript
// On garde chatInput (pour le LLM plus tard) et on ajoute le hash du sessionId.
const crypto = require('crypto');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');
return { json: { chatInput: $json.chatInput, session_hash: sha256($json.sessionId) } };

