-- Nœud Postgres « Fermer session » (Execute Query)
-- Query Parameters : {{ [$json.session_hash] }}
-- Un DELETE seul ne renvoie aucune ligne : n8n s arrêterait avant le message. On compte donc les lignes supprimées dans un SELECT.
WITH d AS (DELETE FROM sessions WHERE token_hash = $1 RETURNING 1)
SELECT count(*) AS closed FROM d;

