// Nœud Code « Valider extraction » — mode « Run Once for Each Item », langage JavaScript
// Le LLM peut se tromper ou être manipulé : on ne fait confiance à RIEN de ce qu'il renvoie.
const raw = String($json.text ?? '');
let d = {};
try {
  const m = raw.match(/\{[\s\S]*\}/);           // tolère du texte ou des ``` autour du JSON
  d = m ? JSON.parse(m[0]) : {};
} catch (e) {
  d = {};
}

const intent = ['set_prefs', 'show_prefs', 'other'].includes(d.intent) ? d.intent : 'other';

// Sujets : liste de chaînes courtes, caractères simples, sans doublon, 10 max
let topics = Array.isArray(d.topics) ? d.topics : [];
topics = [...new Set(
  topics.map((t) => String(t).trim().toLowerCase())
        .filter((t) => /^[\p{L}\p{N} +#.'-]{2,40}$/u.test(t))
)].slice(0, 10);

// Heure : "8:00", "08:00", "8h", "8h30" -> "HH:MM", sinon rien
let time = '';
const tm = String(d.send_time ?? '').trim().match(/^(\d{1,2})\s*[:h]\s*(\d{2})?$/i);
if (tm) {
  const h = Number(tm[1]);
  const min = Number(tm[2] ?? 0);
  if (h <= 23 && min <= 59) time = String(h).padStart(2, '0') + ':' + String(min).padStart(2, '0');
}

// Fuseau : accepté seulement si Node le connaît (ex. "Europe/Paris")
let tz = '';
if (typeof d.timezone === 'string' && /^[A-Za-z_]+\/[A-Za-z_\/-]+$/.test(d.timezone)) {
  try { new Intl.DateTimeFormat('fr', { timeZone: d.timezone }); tz = d.timezone; } catch (e) {}
}

const write = intent === 'set_prefs';
return {
  json: {
    // user_id vient TOUJOURS de la session vérifiée, jamais du texte du chat
    user_id: $('Verifier session').item.json.user_id,
    intent,
    topics_json: write && topics.length ? JSON.stringify(topics) : '',
    send_time: write ? time : '',
    timezone: write ? tz : '',
  },
};

