-- Nœud Postgres « Donner consentement » (Execute Query)
-- Query Parameters : {{ [$json.user_id] }}
-- Ne réécrit pas la date si l'user avait déjà accepté. Trace dans audit_log (preuve RGPD).
-- Le SELECT final renvoie toujours 1 ligne, sinon n8n s'arrêterait avant le message.
WITH u AS (
  UPDATE users SET consent_at = now()
  WHERE id = $1 AND consent_at IS NULL
  RETURNING id
), a AS (
  INSERT INTO audit_log (user_id, action) SELECT id, 'consent' FROM u
)
SELECT count(*) AS updated FROM u;

-- Nœud Postgres « Abonnement » (Execute Query) — sert à /stop ET /reprendre
-- Query Parameters : {{ [$json.user_id, $json.unsubscribed] }}
-- $2 = true pour /stop, false pour /reprendre. La partie newsletter n'envoie qu'aux unsubscribed = false.
WITH u AS (
  UPDATE users SET unsubscribed = $2
  WHERE id = $1
  RETURNING id, unsubscribed
), a AS (
  INSERT INTO audit_log (user_id, action)
  SELECT id, CASE WHEN unsubscribed THEN 'unsubscribe' ELSE 'resubscribe' END FROM u
)
SELECT count(*) AS updated FROM u;

