// Nœud Code « Router » — mode « Run Once for Each Item », langage JavaScript
// Placé sur la sortie VRAI de « Session valide ? » : l'user est connecté.
// Décide de la route. Toute la logique de droits est ICI, pas dans le LLM.
const s = $json;                                   // ligne de « Verifier session »
const cmd = $('Hasher session').item.json.cmd;

let route;
if (cmd === 'accept') route = 'accept';
else if (cmd === 'mydata') route = 'mydata';      // droit d'accès : même sans consentement
else if (cmd === 'delete') route = 'delete';      // droit à l'effacement : même sans consentement
else if (!s.consent_at) route = 'need_consent';   // tout le reste est bloqué sans /accepte
else if (cmd === 'stop' || cmd === 'resume') route = 'subscription';
else route = 'llm';

return { json: { user_id: s.user_id, route, unsubscribed: cmd === 'stop' } };

// Nœud Code « Réponse mes données » — mode « Run Once for Each Item », langage JavaScript
const d = $json;
const date = (v) => (v ? new Date(v).toLocaleString('fr-FR', { timeZone: d.timezone || 'UTC' }) : 'non');
const topics = Array.isArray(d.topics) && d.topics.length ? d.topics.join(', ') : 'aucun';

const lines = [
  '**Ce que Persona stocke sur toi :**',
  '- Email : ' + d.email,
  '- Compte créé le : ' + date(d.created_at),
  '- Consentement donné le : ' + date(d.consent_at),
  '- Envois : ' + (d.unsubscribed ? 'arrêtés (/reprendre pour relancer)' : 'actifs'),
  '- Sujets : ' + topics,
  '- Heure d\'envoi : ' + (d.send_time ?? 'non définie') + ' (' + (d.timezone ?? 'UTC') + ')',
  '- Newsletters déjà envoyées : ' + d.newsletters_sent,
  '- Sessions de connexion actives : ' + d.active_sessions,
  '',
  'Pour tout supprimer : /supprimer',
];
return { json: { output: lines.join('\n') } };

