-- Nœud Postgres « Supprimer compte » (Execute Query) — droit à l'effacement RGPD
-- Query Parameters : {{ [$json.user_id] }}
-- DELETE users => ON DELETE CASCADE supprime sessions, preferences, sent_log.
-- login_codes n'a pas de lien vers users (clé = email) : on le vide à la main.
-- audit_log garde la trace de l'action, sans user_id (donc sans donnée perso).
WITH u AS (
  DELETE FROM users WHERE id = $1 RETURNING lower(email) AS email
), c AS (
  DELETE FROM login_codes WHERE email IN (SELECT email FROM u)
), a AS (
  INSERT INTO audit_log (user_id, action) SELECT NULL, 'delete_account' FROM u
)
SELECT count(*) AS deleted FROM u;

