// Nœud Code « Réponse préférences » — mode « Run Once for Each Item », langage JavaScript
// Construit la réponse du chat à partir de ce qui est VRAIMENT en base (RETURNING).
const p = $json;
const intent = $('Valider extraction').item.json.intent;
const topics = Array.isArray(p.topics) ? p.topics : [];

const lines = [];
if (intent === 'other') {
  lines.push("Je m'occupe de tes sujets et de ton heure d'envoi. Exemple : « l'informatique et le sport à 8h, heure de Paris ».");
}
lines.push('Sujets : ' + (topics.length ? topics.join(', ') : 'aucun'));
lines.push('Heure d\'envoi : ' + (p.send_time ?? 'non définie') + ' (' + p.timezone + ')');

const missing = [];
if (!topics.length) missing.push('tes sujets (ex. « l\'informatique, le sport »)');
if (!p.send_time) missing.push('ton heure d\'envoi (ex. « 8h »)');
if (missing.length) lines.push('Il me manque ' + missing.join(' et ') + '.');
else if (p.timezone === 'UTC') lines.push('Fuseau UTC par défaut : dis-moi ta ville si ce n\'est pas le bon.');
else lines.push('Tout est bon, ta newsletter partira à cette heure-là.');

return { json: { output: lines.join('\n') } };
